window.TEXTP["9.39"] = [{"n":796,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.8,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c","<b><i>в сделке; получение прибыли с того, за что человек не несёт ответственности; а также продажа того, чего у тебя нет».</i></b> Хадис привели Ахмад (2/179), Абу Дауд (3504), ан-Насаи (7/295) и ат-Тирмизи (1234), подтвердивший его достоверность. Также достоверность этого хадиса подтвердили Ибн Хузайма и аль-Хаким."],["p","Что же касается двух условий в сделке, то смыслом этого является то, что когда один говорит другому: «Я продаю тебе это за тысячу, если деньги дашь сразу, а если в рассрочку — то за две тысячи»<sup>71</sup>."],["p","Также есть мнение, что это когда один говорит другому: «Я продаю тебе эту одежду за такую-то цену, а также обязуюсь подшить её»."],["p","Ад-Дахляуи в «аль-Худжа аль-балига» говорит: <i>«Суть наличия двух условий в рамках одной сделки в том, чтобы обусловить соблюдение всех прав самой сделки и одновременно обусловить наличие чего-то, не относящегося к ней, например, получить подарок или заступничество перед кем-то. Либо если покупатель решит продать купленный товар, поставить условием, чтобы не продавал никому, кроме него. Это и есть два условия в рамках одной сделки»<sup>72</sup>.</i>"],["h","<b>• ВОПРОС № 33: ДВЕ ТОРГОВЫЕ СДЕЛКИ В ОДНОЙ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«…и две сделки в рамках одной…».</i>",{"mt":0.34}],["p","Исходя из хадиса Абу Хурайры, который приводят Ахмад (2/432), ан-Насаи (7/324), Абу Дауд (3461) и ат-Тирмизи (1231), подтвердивший его достоверность, о том, что пророк (да благословит его Аллах и приветствует) запретил заключать две сделки в рамках одной."],["p","А в версии у Абу Дауда (3461) говорится: <b><i>«Тому, кто объединил две сделки в одну, полагается та из них, цена которой ниже, а иначе это будет ростовщичеством».</i></b>"]],"notes":[[71,"Сыддик Хасан Хан в следующей главе разбирает ошибочность данного разъяснения."],[72,"В «ат-Тахзиб» (5/144) приводятся слова Ибн аль-Кайима, который, разъясняя суть двух условий в рамках одной сделки, сказал, что это когда один продаёт другому товар за десять в рассрочку, с тем, чтобы он выкупил у него этот же товар дешевле, расплатившись сразу же. А это ни что иное, как запретная ростовщическая сделка, известная, как «аль-гына». См. «ат-Та‘ликат ар-радыййа» (2/378)."]]},{"n":797,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","blocks":[["p","Ахмад (3725) привёл хадис со слов ‘Абду-Ллаха ибн Мас‘уда, который сказал: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>запретил объединение двух сделок в одну».</i> Симак ибн Харб сказал: <i>«Это когда человек, заключая сделку, говорит: “В рассрочку стоит столько-то, а если сразу — столько-то”».</i>"],["p","Все передатчики данного сообщения являются надёжными<sup>73</sup>."],["p","Здесь Симак разъясняет смысл объединения двух сделок в одну. В предыдущей главе уже упоминалось точно такое же разъяснение относительно двух условий в рамках одной сделки, и оно является неправильным. Однако под двумя условиями в рамках одной сделки имеется в виду именно наличие в одной сделке двойных условий, тогда как в данной главе говорится о двух разных сделках, объединённых в одну."],["p","Абу Мухаммад аль-Багави в «Шарху с-Сунна» говорит: <i>«Учёные по-разному объясняли объединение двух сделок в одну:</i>"],["p","— одни сказали, что имеются в виду слова: «Я продаю тебе эту одежду за десять, если расплачиваешься сейчас, и продаю за двадцать, если расплатишься в течение года (и, заключив сделку, расходятся, не договорившись на чём-то одном)». Эта сделка недействительна по мнению большинства учёных. Но если они договорятся на чём-то одном, прежде чем разойдутся, их сделка действительна, относительно чего среди учёных нет разногласий."],["p","— другие сказали, что имеются в виду слова: «Я продаю тебе своего невольника за двадцать динаров, если ты потом продашь мне свою невольницу». И такая сделка недействительна, так как ценой невольника являются двадцать динаров плюс условие о продаже ему в будущем невольницы (отдельной сделкой). Такое условие необязательно к исполнению, но, являясь частью цены, приводит к недействительности части стоимости. Это в свою очередь приводит к неизвестности количества товара, которой соответствует оставшаяся часть его стоимости."],["p","Однако, если две вещи будут проданы вместе в рамках одной сделки, как если кто-то продаст и дом, и невольника, назначив одну общую"]],"notes":[[73,"Некоторые имамы считали, что данный хадис является достоверным именно как слова самого Ибн Мас’уда, а не пророка (да благословит его Аллах и приветствует). См. «ад-Дирая» (2/152)."]]},{"n":798,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","цену, то это дозволено, и не имеет отношения к объединению двух сделок в одну, а является одной сделкой, заключённой на две вещи в совокупности»."],["p","Что касается продажи товара в рассрочку дороже её рыночной стоимости в настоящий момент, то я считаю, что данная надбавка не имеет отношения к ростовщичеству ни с какой стороны. Ведь ростовщичество — это взаимообмен неодинаковых количеств одного и того же вида товара. А нет одинаковости между товаром и тем, что служит его ценой, если они относятся к разным категориям. Поэтому неправильно запрещать данный вид сделки, приписывая его к ростовщичеству."],["p","Если же кто-то скажет, что запрет в данном случае связан с отсрочкой оплаты, то ни для кого не секрет, что для запрещения подобного необходимо иметь шариатский довод. Данный вопрос, конечно же, нуждается в более подробном исследовании. Поэтому автор (аш-Шаукани) посвятил ему отдельную работу, назвав её «Шифау ль-‘иляль фи хукми з-зиядати ли-аджалиль-аджаль»."],["p","В качестве аргумента на запрет можно использовать хадис Абу Хурайры, который приводят Ахмад (2/432), ан-Насаи (7/324), Абу Дауд (3461) и ат-Тирмизи (1231), подтвердивший его достоверность, о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Тому, кто объединил две сделки в одну, полагается цена за ту из них, которая ниже, а иначе это будет ростовщичеством».</i></b>"],["p","А также упоминавшийся хадис, который привели Ахмад, аль-Баззар и ат-Табарани в «аль-Кабир» и в «аль-Авсат» со слов Симака от ‘Абду р-Рахмана ибн ‘Абду-Ллаха ибн Мас‘уда от его отца, который сказал: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>запретил объединение двух сделок в одну».</i> Симак сказал: <i>«Это когда продавец говорит: “В рассрочку стоит столько-то, а если заплатишь сразу — столько-то”».</i>"],["p","Аль-Хайсами в «Маджма‘у з-заваид» сказал, что все передатчики Ахмада в этом хадисе надёжные."],["p","Эти два хадиса указывают на запрет надбавки в цене по причине отсроченной оплаты, и по этой причине пророк (да благословит его Аллах и приветствует) сказал: <b><i>«…тому полагается та цена, которая ниже, а иначе это будет ростовщичеством».</i></b>"]],"notes":[]},{"n":799,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":46.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Общий смысл этих хадисов включает в себя также и те товары, которые изначально не относятся к ростовщическим категориям."],["p","Однако большинство учёных склонилось к дозволенности увеличения цены товара по причине отсрочки оплаты и не согласились с тем, что в этих двух хадисах подразумевается этот смысл<sup>74</sup>."],["h","<b>• ВОПРОС № 34: ЗАПРЕТ ИМЕТЬ ПРИБЫЛЬ С ТОГО, ЗА ЧТО ЧЕЛОВЕК НЕ ОТВЕЧАЕТ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«…и прибыль с того, за что человек не несёт ответственность…».</i>",{"mt":0.34}],["p","Исходя из приведённого ранее хадиса: <i><b>«Недозволены: предоставление займа с условием заключения торговой сделки; два условия в одной сделке; получение прибыли с того, за что человек не несёт ответственности; а также продажа того, чего у тебя нет»</b><sup>75</sup><b>.</b></i>"],["p","Сутью этого запрета является то, что человек не должен продавать то, за что не несёт ответственности, как например, если продаёт то, что купил, но ещё не забрал у продавца."],["h","<b>• ВОПРОС № 35: ПРОДАЖА ТОГО, ЧЕГО НЕТ В НАЛИЧИИ У ПРОДАВЦА</b>",{"mt":0.3,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«…и продажа того, чего нет в наличии у продавца…»<sup>76</sup>.</i>",{"mt":0.34}]],"notes":[[74,"Это объясняется тем, что если стороны договорились на одной из упомянутых цен, будь то на цене в рассрочку или цене мгновенной оплаты, то это уже никак не может относиться к двум сделкам в рамках одной, на что имам аль-Багави привёл единогласное мнение учёных. Однако если их сделка свершилась, продолжая содержать в себе обе цены в зависимости от условий оплаты, то именно к этому относятся хадисы данной главы, а также и слова учёных, разъясняющих их с приведением подобных примеров. А Аллаху об этом ведомо лучше."],[75,"Ахмад (2/179), ан-Насаи (7/295), ад-Дарими (2/253), ад-Даракутни (3/74), ат-Тахауи (4/46). Хадис достоверный. См. «Сахиху т-Тирмизи» (1234)."],[76,"К этому не относится ни сделка «ас-салям», речь о которой пойдёт в соответствующей главе, ни «аль-истисна», которую часть учёных относила к «ас-салям», а другие относили к отдельному виду торговых взаимоотношений. Шейх Суляйману р-Рухайли сказал: <i>«Аль-Истисна — это когда за определённую плату производится заказ на изготовление чего-либо с определённым опи-</i> <i>санием и свой ствами из материалов, принадлежащих изготовителю. То есть, когда покупатель желает приобрести что-то, он отправляется к производителю или же ремесленнику, и заказывает у него это, заранее договариваясь о цене и описании конечного продукта. Это и есть «аль-истисна». К примеру, человек идёт к портному, чтобы он за некую плату сшил для него определённую одежду из материала и всех остальных комплектующих, принадлежащих портному.</i> Однако если тот же человек отправится к портному, увидит у него некий материал за некую цену и купит его у него, а затем скажет ему: «Теперь сшей мне из этого куска материи такую-то одежду», договорившись с ним о стоимости этой работы, то в данном случае это не будет «аль-истисна». Вначале это будет относиться к купле-продаже, а затем к найму. Так как вначале состоялась сделка по покупке материала, а затем сделка по найму для шитья одежды. И это не называется аль-истисна, так как для него необходимо, чтобы материал также принадлежал изготовителю, и чтобы стоимость изделия включала в себя как сам материал, так и работу. Аль-Истисна дозволен, по единогласному мнению учёных, однако они разногласили относительно того, к какому именно виду торговых сделок его отнести. Основных мнений два:"]]},{"n":800,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Исходя из хадиса Хакима ибн Хизама, который обратился к пророку (да благословит его Аллах и приветствует) со словами: <i>«О, посланник Аллаха, ко мне обращаются с просьбой продать что-либо, чего у меня нет, и я сначала продаю это, а уже затем иду и приобретаю это на рынке»,</i> — на что посланник Аллаха (да благословит его Аллах и приветствует) ответил: <b><i>«Не продавай то, чего у тебя нет».</i></b> Этот"]],"notes":[[1,"Отнесение «аль-истисна» к сделке «ас-салям», из чего следует применение в отношении него всего того, чем обусловлена сделка «ас-салям»."],[2,"Другое мнение заключается в том, что «аль-истисна» — это самостоятельный вид сделки похожий на «ас-салям», но всё же не являющийся им. И правильным, по моему мнению, является мнение второй группы, а Аллаху это ведомо лучше. Условия действительности «аль-истисна»:"],[1,"Детальное разъяснение вида изготавливаемой вещи, её свойств и описания."],[2,"Установление срока изготовления заказа."],[3,"Сделка заключается лишь между покупателем и изготовителем. <i>И этот последний пункт очень важен, чтобы люди не прибегали к продаже того, чем не владеют, прикрываясь данным видом торговой операции. Например, дозволено купить у строительной компании квартиру или дом, прежде чем он будет построен. Однако купивший таким образом квартиру или дом, не может перепродать его на стадии строительства (пока не будет завершена постройка и не произойдёт акт приёма-передачи между заказчиком и изготовителем)».</i> См. «Фикху ль-му‘амаляту ль-му‘асыра» (100–104)."]]},{"n":801,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","blocks":[["c","хадис привели Ахмад и авторы сборников «ас-Сунан», а его достоверность подтвердили ат-Тирмизи и Ибн Хиббан."],["p","Под словами пророка (да благословит его Аллах и приветствует) <b><i>«то, чего у тебя нет»</i></b> имеется в виду то, что не принадлежит тебе и то, над чем ты не властен."],["p","К продаже того, чего нет, относится продажа того, что принадлежит другому, без его ведома. В этом присутствует неизвестность, ведь продавец не знает, согласится ли хозяин товара с этой сделкой или нет. И это соответствует мнению аш-Шафи‘и."],["p","Абу Ханифа сказал, что сделка дозволена, однако её действительность привязана к получению согласия истинного владельца товара<sup>77</sup>."],["p","Поэтому, из-за недействительности продажи того, чего нет у продавца, учёные запрещали продажу накладных, именуемых долями («аль-кутут» или «ас-сукук»), прежде чем товар, указанный в них, не достигал тех, для кого они были выписаны, и они не овладевали товаром в полной мере. И только после этого им дозволялось продать этот товар."],["p","«Аль-кутут» — означает то же самое что и «ас-сукук», то есть предписанные доли. С таким же смыслом это слово приходит в Коране: <b>«Неверующие сказали: «Господь наш! Приблизь, предназначенное для нас наказание, нашу долю (кытта) до наступления Судного Дня»</b><sup>78</sup><b>.</b>"]],"notes":[[77,"В фикхе это положение именуется «бай‘у ль-фудули», а на его дозволенность аргументируют хадисом, приводимым у аль-Бухари (3642) со слов ‘Урвы ибн Аби ль-Джа‘да о том, что пророк (да благословит его Аллах и приветствует) дал ему динар, чтобы он купил ему на него барана. Однако ‘Урва купил на динар двух баранов, затем продал одного за динар и вернулся к пророку (да благословит его Аллах и приветствует) с бараном и динаром. Увидев это, пророк (да благословит его Аллах и приветствует) обратился к Аллаху с мольбой, чтобы Он даровал ему благодать (барака) в его торговле, в результате чего стало так, что даже если бы он купил глину, и тогда получил бы прибыль с этого. При этом надо учесть, что в хадисе описывается ситуация с более выгодным приобретением, а также и то, что ‘Урва был изначально уполномочен для совершения сделки."],[78,"Сура «Сад», аят 16."]]},{"n":802,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.9,"mt":0,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":64.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","<b>• ВОПРОС № 36: ПРАВО НА РАСТОРЖЕНИЕ СДЕЛКИ ПРИ НЕСОБЛЮДЕНИИ ЕЁ УСЛОВИЙ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Дозволяется обусловливание сделки отсутствием в ней обмана…».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах со слов Ибн ‘Умара, который сказал: <i>«Некий человек пожаловался посланнику Аллаха</i> (да благословит его Аллах и приветствует) <i>на то, что его обманывают в торговле и пророк</i> (да благословит его Аллах и приветствует) <i>сказал ему: <b>«При заключении сделок говори: «Без обмана»»</b><sup>79</sup><b>.</b></i>"],["p","Есть и другие хадисы по данной теме."],["p","А под обманом (аль-хиляба) имеется в виду хитрость. Внешне хадис указывает на то, что сказавший и обусловивший это, имеет право на расторжение сделки в любом случае, обманут он был или нет<sup>80</sup>."],["h","<b>• ВОПРОС № 37: ПРАВО НА РАСТОРЖЕНИЕ СДЕЛКИ В ОДНОСТОРОННЕМ ПОРЯДКЕ ДО ТЕХ ПОР, ПОКА СТОРОНЫ НЕ РАЗОШЛИСЬ</b>",{"mt":0.3,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«Право на расторжение сделки закреплено за каждой из сторон до тех пор, пока они не разошлись».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах со слов Хакима ибн Хизама о том, что пророк (да благословит его Аллах и приветствует) сказал: <i><b>«Стороны, имеют право на расторжение сделки до тех пор, пока они не расстанутся»</b><sup>81</sup><b>.</b></i>"]],"notes":[[79,"Малик (2/685), аль-Бухари (2118, 4964), Муслим (1533)."],[80,"Шейх аль-Альбани сказал: <i>«С этим утверждением нельзя согласиться, наоборот, внешне этот хадис указывает на то, что право на расторжение сделки предоставляется, если в ней человек был введён в заблуждение. Однако такой вывод можно сделать с другого хадиса, который привели Ибн Маджа (2/61) и ад-Даракутни (312), в котором говорится, что пророк</i> (да благословит его Аллах и приветствует) <i>сказал ему:</i> <b><i>«Когда ты заключаешь сделку, говори, «Без обмана», и что бы ты ни приобрёл, у тебя будет право на расторжение сделки в течение трёх дней. И если ты доволен приобретением, то удержи его, а если нет — верни его хозяину».</i></b> <i>Относительно достоверности этого хадиса были разногласия, но хадис достоверен, а с его подробным разбором вы можете ознакомиться в «ас-Сильсилю с-сахиха» (2874)»</i>. См. «ат-Та‘ликату р-радыййа» (2/383)."],[81,"Аль-Бухари (2079, 2082, 2108, 2110, 2114), Муслим (1532)."]]},{"n":803,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","blocks":[["p","В тех же источниках приводится похожий хадис со слов Ибн ‘Умара. Также по этой теме есть и другие хадисы."],["p","А также в «аль-Муватта» со слов Ибн ‘Умара передаётся, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <i><b>«Каждая из сторон сделки имеет право расторгнуть её только до тех пор, пока они не разошлись, за исключением обусловленной сделки (с правом на расторжение в течение большего времени)»</b><sup>82</sup><b>.</b></i>"],["p","В числе сподвижников, признававших право на расторжение сделки в рамках встречи, в которой она была заключена (хияру ль-маджлис), были ‘Али, Абу Барза аль-Аслями, Ибн ‘Умар, Ибн ‘Аббас, Абу Хурайра и другие. А среди их последователей (таби‘инов) на этом мнении были Шурайх, аш-Ша‘би, Тавус, ‘Ата, и Ибн Аби Муляйка, о чём сообщил аль-Бухари."],["p","Вдобавок, Ибн аль-Мунзир передал это же мнение от некоторых учёных Медины<sup>83</sup>, как Са‘ид ибн аль-Мусайиб, Ибн Шихаб аз-Зухри, Ибн Аби Зиб, а также от аль-Хасана аль-Басри, аль-Ауза‘и, Ибн Джурайджа и других. А Ибн Хазм сказал, что неизвестно, чтобы кто-то ещё противоречил им в этом вопросе, кроме ан-Наха‘и. Однако это является преувеличением."],["p","Это же мнение аль-Махди в «аль-Бахр» передаёт и от аш-Шафи‘и, Ахмада, Исхака и Абу Саура."],["p","Что же касается ханафитов, маликитов и некоторых других, то они посчитали, что если сделка заключена и завершена, то ни у кого нет права на её расторжение в одностороннем порядке. И всё же истина на стороне учёных, придерживающихся первого мнения."]],"notes":[[82,"Аль-Бухари (2108, 2109, 2111, 2113), Муслим (1531)."],[83,"Акцент на учёных Медины делается по той причине, что аргументом имама Малика в непринятии данного положения являлось именно то, что он опирался на единогласное мнение учёных Медины, но как мы видим, они не были единогласны в этом вопросе. При этом следует отметить, что ни к мнению учёных Медины, ни к согласованному мнению имамов четырёх мазхабов, нельзя распространять положения, которые относятся к единогласному мнению (аль-иджма’). Вдобавок к этому, они никак не могут быть противопоставлены достоверному пророческому хадису!"]]},{"n":804,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","ГЛАВА 2. РОСТОВЩИЧЕСТВО (РИБА́)",{"z":1.29}],["h","<b>• ВОПРОС № 1: СУЖДЕНИЕ РЕЛИГИИ О РОСТОВЩИЧЕСТВЕ</b>",{"mt":0.3,"fr":1}],["p","Всевышний Аллах сказал: <b>«Те, которые пожирают ростовщический излишек, восстанут, как восстаёт тот, кого сатана поверг своим прикосновением. Это потому, что они говорили: «Воистину, торговля подобна ростовщичеству». Но Аллах дозволил торговлю и запретил ростовщичество»</b><sup>84</sup><b>.</b>",{"mt":0.34}],["p","Также Всевышний сказал: <b>«О те, которые уверовали! Бойтесь Аллаха и не берите оставшуюся часть лихвы, если только вы являетесь верующими. Но если вы не подчинитесь в этом, то знайте, что Аллах и Его посланник объявляют вам войну»</b><sup>85</sup><b>.</b>"],["p","Учёные единогласны относительно того, что ростовщичество относится к величайшим грехам, и что ростовщическая сделка недействительна, а должник обязан вернуть только сумму самого долга без начислений. Если же должник не способен расплатиться с долгом, ему предоставляется отсрочка до тех пор, пока он сможет выплатить."],["p","Данное положение берётся из Книги Аллаха, в которой говорится: <b>«А если вы раскаетесь, то вам полагается ваш первоначальный капитал»</b><sup>86</sup><b>.</b>"],["p","Из этого аята понимается, что, если ростовщик не покаялся, судья может изъять его деньги. Также этим аятом аргументируют дозволенность изъятия у ростовщика его прибыли сверх основного капитала, несмотря на то покаялся он или нет."],["p","Итак, при отсутствии покаяния ростовщика, судья может изъять у него всю сумму, а именно: основной капитал и начисленные на неё проценты. Если же он покаялся, изъятию подлежит лишь сумма оплаченных процентов сверх основного капитала."]],"notes":[[84,"Сура «аль-Бакара», аят 275."],[85,"Сура «аль-Бакара», аяты 278–279."],[86,"Сура «аль-Бакара», аят 279."]]},{"n":805,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","frames":[{"s":"a","h":46.9,"mt":0,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","<b>• ВОПРОС № 2: РОСТОВЩИЧЕСКИЕ ТОВАРЫ И СУЖДЕНИЕ РЕЛИГИИ О НИХ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Запрещён обмен золота на золото, серебра на серебро, пшеницы на пшеницу, ячменя на ячмень, фиников на финики и соли на соль, кроме как в равных количествах и из рук в руки».</i>",{"mt":0.34}],["p","Но если обмен (бартер) происходит между разными категориями товаров, можно продавать их в каких угодно количествах, если обмен ими происходит из рук в руки в течение встречи (т. е. без возникновения задолженности)."],["p","Эти шесть категорий товаров были упомянуты в хадисах, как например, в хадисе от Абу Са‘ида аль-Худри, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Обмен золота на золото, серебра на серебро, пшеницы на пшеницу, ячменя на ячмень, фиников на финики, соли на соль должен происходить в равных количествах и из рук в руки. А кто добавит другому или себе, совершит ростовщичество. Берущий лишнее и дающий его одинаковы в грехе».</i></b> Хадис приводится у Муслима, а другие подобные хадисы приводятся в обоих сборниках достоверных хадисов аль-Бухари (2176, 2177) и Муслима (1584) и у других, однако ограничиваются только перечислением этих шести категорий товаров<sup>87</sup>."]],"notes":[[87,"Шейх аль-Альбани сказал: <i>«В сборнике у аль-Байхакы есть добавка:</i> <b><i>«…и это относится ко всему, что отмеряется и взвешивается»</i></b><i>, однако в цепочке передатчиков присутствует Хиббан ибн ‘Убайду-Ллах. Сам аль-Байхакы после приведения хадиса сказал, что этого передатчика не считали надёжным. Но с этими его словами не согласился Ибн Туркумани и привёл слова имамов, считавших его надёжным. Также аль-Хаким привёл от него хадис и сказал, что иснад его достоверный. Также данный хадис подтверждается другим хадисом от Абу Са‘ида и Абу Хурайры, в котором говорится, что посланник Аллаха</i> (да благословит его Аллах и приветствует) <i>назначил ответственного за трофеи Хайбара, и однажды, когда он принёс хорошие финики, пророк</i> (да благословит его Аллах и приветствует) <i>спросил его:</i> <b><i>«Все ли финики Хайбара такие хорошие?».</i></b> <i>Он ответил: «Нет», — и сказал, что они обменивают два са‘а фиников Хайбара на один са‘а этих (хороших) фиников или же три са‘а из тех на два са‘а этих. Пророк</i> (да благословит его Аллах и приветствует) <i>сказал:</i> <b><i>«Не делай так, однако продай те финики за дирхамы, а потом за эти дирхамы купи финики хорошего сорта»</i></b> <i>и добавил:</i> <b><i>«…и так же в отношении всего, что взвешивается».</i></b> <i>(аль-Бухари 2302, ат-Тахави «аль-Мушкиль» 2/122, аль-Байхакы 5/585).</i> <i>Ибн Таймия в «аль-Мунтака» говорит: «Этот хадис является доводом на то, что под ростовщические товары подпадает бартер всего того, что продаётся по весу, так как слова «и так же в весах», то есть в том, что взвешивается, а иначе сами весы относились бы к ростовщическим товарам». (10/2248)».</i> См. «ат-Та‘ликату р-радыййа» (2/386)."]]},{"n":806,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Уалию-Ллах ад-Дахляуи в «аль-Худжа аль-балига» говорит: <i>«Учёные из числа правоведов поняли из этих текстов, что в ростовщичество попадают не только эти перечисленные в хадисах шесть категорий товаров, но также все схожие с ними товары».</i>"],["p","Абу Мухаммад аль-Багави в «Шарху с-сунна» (8/58) говорит: <i>«Учёные сошлись на том, что ростовщичество происходит при бартере этих шести категорий товаров, которые были упомянуты в хадисе. Также большинство из них посчитало, что данное положение не ограничивается именно этими товарами, а включает в себя все товары с подобным описанием. Они сказали, что ростовщичество в отношении дирхамов и динаров имеет одно описание, а в отношении оставшихся четырёх товаров — другое описание.</i>"],["p","После чего разошлись во мнениях относительно конкретизации этого описания. Аш-Шафи‘и сказал, что в отношении дирхамов и динаров учитывается то, что они служат деньгами. А Абу Ханифа сказал, что причиной всего является взвешивание, что даже железо, медь и хлопок подпадают под ростовщичество."],["p","<i>Аш-Шафи‘и в своём предыдущем мазхабе, так же, как и Са‘ид ибн аль-Мусайиб, придерживался мнения, что эти четыре товара (пшеница, ячмень, финики и соль) подпадают под ростовщичество потому, что они относятся к продуктам питания, которые взвешивают или же отмеряют. А в новом мазхабе причиной назвал лишь то, что они относятся к продуктам питания. Из чего следует, что под ростовщичество может попасть всё, что употребляется в пищу, как плоды, фрукты, овощи и лекарства. Он изменил своё мнение по причине обнаружения хадиса: <b>«Еда обменивается на еду в одинаковых количествах»</b><sup>88</sup>, где шариатское постановление (хукм) распространяется на всё то, что включает в себя понятие «еда». Абу Ханифа же сказал, что ростовщичество в этих четырёх продуктах связано с тем, что их отмеряют, из чего следует, что данное положение охватывает всё то, что обычно продаётся отмериванием, включая гипс и известь».</i>"]],"notes":[[88,"Муслим (1592)."]]},{"n":807,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","И далее будет приводиться то, что опровергает вышеперечисленные мнения."],["h","<b>• ВОПРОС № 3: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ЕЩЁ ОТНОСИТСЯ К РОСТОВЩИЧЕСКИМ ТОВАРАМ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Существует разногласие относительно приобщения к этим шести также и других товаров».</i>",{"mt":0.34}],["p","Можно ли к этим категориям, упомянутым в хадисе, отнести и другие товары, чтобы при их бартере была такая же шариатская норма (хукм) относительно запрета количественной разности и отсрочки, когда оба товара относятся к одной категории; или же только запрета отсрочки, когда категории разнятся, но подпадают под одно описание?"],["p","Мазхаб захиритов считал, что к этим шести категориям товаров не причисляется ничего другого. Этому мнению также отдал предпочтение ас-Сан‘ани в «Субулю с-салям» и сказал, что посвятил этой теме отдельный труд, который назвал «аль-Кавлю ль-муджтаби». А более подробно об этом можно прочесть в книге «Миску ль-хитам»."],["p","Все остальные учёные склонились к тому, что, если другие товары имеют общие характеристики с упомянутыми в хадисе, они имеют такую же шариатскую норму (хукм). При этом учёные разошлись во мнениях относительно описания, которое должно объединять сравниваемые товары. Некоторыми было сказано, что это совпадение в категории вместе с отмериванием или взвешиванием при продаже. Они аргументируют своё мнение хадисом, который привёл ад-Даракутни (2/589) и аль-Баззар (4/354) со слов аль-Хасана от ‘Убады и Анаса, что пророк (да благословит его Аллах и приветствует) сказал: <i><b>«Всё, что продаётся на развес должно обмениваться (при бартере) в равных количествах, если относится к одному виду, как и всё то, что отмеривается. Если же товар относится к разным видам, то нет проблем в количественной разности обмениваемых (через бартер) товаров»</b><sup>89</sup><b>.</b></i>"],["p","На этот хадис указал Ибн Хаджар в «ат-Тальхис» и никак его не дискредитировал. В иснаде хадиса присутствует ар-Раби‘ ибн Сабих, которого посчитали надёжным передатчиком Абу Зур‘а и другие."]],"notes":[[89,"Хадис достоверный. См. «ат-Та‘ликату р-радыййа» (2/389)."]]},{"n":808,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","Но некоторые хадисоведы считали его слабым передатчиком. Ахмад сказал о нём, что в нём нет проблем. Яхья ибн Ма‘ин, по одним источникам, также считал, что в нём нет проблем, а по другим — считал его слабым, и возможно даже подтасовывающим хадисы. Ибн Са‘д и ан-Насаи считали его слабым, а Абу Зур‘а и Абу Хатим считали его праведным шейхом. Однако праведность человека не указывает на его надёжность в хадисах<sup>90</sup>. Ведь хафиз Ибн Хаджар в «ат-Такриб» относительно него сказал: <i>«Правдивый, но с плохой памятью».</i> И не секрет, что такой хадис не может быть доводом, тем более в таком великом и ответственном деле, как говорить о продукте, который не упомянут в известном пророческом хадисе, что он относится к ростовщическому. Тогда как известно, что ростовщичество является одним из наитяжелейших грехов перед Аллахом — Свят Он и Велик. Из чего следует, что совершивший его, совершает один из величайших грехов в Шариате. Но вместе с тем, абсолютное большинство учёных, за исключением захиритов, сошлись на том, что к ростовщичеству относятся и другие продукты, имеющие схожее описание."],["p","Данный хадис, указывает на то, что к этим шести видам относятся и другие товары. Также он указывает на причину, по которой они к ним причисляются, а это — отмеривание или взвешивание товаров одного вида."],["p","Также из того, чем утверждается положение ростовщичества в продуктах, помимо шести упомянутых, это хадис, приводимый в обоих Сахихах со слов Ибн ‘Умара, который сказал: <i>«Посланник Аллаха</i> (да благословит его Аллах и приветствует) <i>запретил «аль-музабана» — а это продажа фиников на пальме за отмеренные сушёные</i>"]],"notes":[[90,"Шейх аль-Альбани сказал: <i>«Из слов хадисоведов, когда они говорят «праведный» не понимается лишь то, на что указывает языковой смысл этого слова, однако под этим они имеют в виду, что он приемлем как передатчик. В этом можно убедиться, посмотрев на слова аз-Захаби во вступлении к «аль-Мизан». Так, он говорит, что среди слов, которыми обозначают приемлемых передатчиков, такие как «праведненький» (сувайлих) в уменьшительно-ласкательной форме. А тот, в отношении которого сказали «праведный», без уменьшения, тем более заслуживает этого. Это что касается его описания словом «праведный». И всё же мне стало известно о том, что ар-Раби‘ ибну Сабих обладал слабой памятью, но, несмотря на это, его хадисы классифицируются либо как приемлемые «хасан», либо как достоверные по причине наличия других подтверждающих хадисов «сахих ли-гайрихи».</i> См. «ат-Та‘ликату р-радыййа» (2/389)."]]},{"n":809,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","blocks":[["c","<i>финики или же продажа винограда на винограднике за отмеренный изюм, или же продажа посевов за отмеренные продукты питания. И он запретил всё это».</i> А в версии у Муслима говорится: <i>«…а также продажу любых плодов, прикидывая на глаз их количество»<sup>91</sup>.</i>"],["p","Этот хадис указывает на то, что виноград и изюм также относятся к «аль-музабана»<sup>92</sup>, а версия Муслима относит к ней ещё больше плодов."],["p","Также на отнесение других плодов (фруктов, посевов и овощей) к данному запрету указывает хадис, который привёл Малик в «аль-Муватта» (2/655) со слов Са‘ида ибн аль-Мусайиба о том, что пророк (да благословит его Аллах и приветствует) запретил покупать мясо, расплачиваясь живой скотиной. Этот хадис также привели аш-Шафи‘и и Абу Дауд с нецелостным иснадом. Ад-Даракутни, в отличие он них, привёл его с целостным иснадом в «аль-Гариб» от Малика, а тот — от аз-Зухри от Сахля ибн Са‘да, однако классифицировал этот хадис, как слабый. Поэтому правильным будет считать это сообщение «мурсаль», с чем согласился Ибн ‘Абду ль-Барр."],["p","Есть и другой хадис, который приводится у аль-Баззара со слов Ибн ‘Умара, и который подтверждает смысл данного хадиса, но в его иснаде присутствует Сабит ибн Зухайр, который является слабым передатчиком."],["p","По данному вопросу также приводится хадис от Абу Умайи ибн Я‘ля от Нафи‘а, однако Абу Умайа тоже является слабым передатчиком."],["p","У аль-Хакима (2/35), аль-Байхакы (5/288) и Ибн Хузаймы (3/142) приводится хадис, который сильнее этого, передаваемый со слов аль-Хасана от Самуры<sup>93</sup>."]],"notes":[[91,"Малик (2/624), аль-Бухари (2171, 2175), Муслим (1542)."],[92,"Данное указание в хадисе неявное, однако то, на что действительно указывает хадис — это запрет того, в чём есть неизвестность, как это упоминалось ранее со слов Малика. Продажа плодов пальмы за сушёные финики содержит в себе две причины для запрета: неизвестность и ростовщичество. В итоге, в хадисе нет довода на сказанное. См. «ат-Та‘ликату р-радыййа» (2/390)."],[93,"Этот хадис был ослаблен по причине разногласий, слышал ли аль-Хасану ль-Басри хадисы от Самуры или нет. См. «ат-Та‘ликату р-радыййа» (2/391)."]]},{"n":810,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Также из того, что подтверждает это положение — это хадис Рафи‘а ибн Хадиджа и Сахля ибн Аби Хасамы, который приводится у ат-Тирмизи (1303) в отношении дозволенности «аль-‘арая». В нём говорится: «<i><b>…и запретил продавать виноград за изюм, а также любые плоды, прикидывая на глаз их количество»</b><sup>94</sup><b>.</b></i>"],["p","Также из того, что указывает на необходимость учитывать равенство в весе — это хадис, который приводится у Ахмада и Муслима (1584) со слов Абу Са‘ида, в котором говорится: <b><i>«Не продавайте золото за золото и серебро за серебро, кроме как при равном весе; одинаковое за одинаковое, равное за равное».</i></b>"],["p","Ахмад (2/389, 485), Муслим (1588–85) и ан-Насаи (7/278) привели хадис со слов Абу Хурайры, в котором говорится: <b><i>«При бартере золота на золото должна соблюдаться равность и одинаковость. И при бартере серебра на серебро должна соблюдаться равность и одинаковость».</i></b>"],["p","Также Муслим, ан-Насаи и Абу Дауд привели хадис со слов Фадали ибн ‘Убайда, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Не продавайте золото за золото, кроме как одинаковое по весу».</i></b>"],["p","Что же касается того, что подтверждает необходимость учитывать меру, то это хадис Ибн ‘Умара, о котором упоминалось ранее, и в котором говорится: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>запретил продажу винограда за отмеренный изюм»<sup>95</sup>.</i>"],["p","А также исходя из того, о чём скоро пойдёт речь, относительно запрета продажи кучи чего-либо, вес которой неизвестен."],["p","Я скажу, что среди учёных, признающих аналогию (аль-кыяс), есть разногласия в отнесении продуктов, кроме упомянутых, к ростовщическим. Между тем ни у одной из этих групп нет ярких и ясных доводов, у них лишь голые предположения и догадки, к которым они присоединили длинные рассуждения, от которых нет прока. Одни говорят, что к установлению причины их привёл один из путей выявления и установления причин, как выявление и извлечение его описания. Другие сказали, что пришли к тому, к чему они пришли, другим путём выявления причин, как например, методом исключения"]],"notes":[[94,"Этот хадис приводится также у аль-Бухари (2383)."],[95,"Малик (2/624), аль-Бухари (2171, 2175), Муслим (1542)."]]},{"n":811,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","blocks":[["c",". И мы ни в коем случае не отрицаем использование этих путей для выявления причин и установления шариатских норм, однако мы не согласны с их описанием того, что является причиной в данном случае. Нет ничего лучше, чем ограничиться шариатскими текстами, не прибегая к обременению себя переходом его границ, не возлагая на рабов Аллаха то, что станет для них тяжело выполнимым. Тем не менее, мы не отрицаем аналогию (аль-кыяс), как довод, но мы отрицаем приближение посредством неё к Аллаху, помимо тех случаев, когда причина шариатской нормы (хукм) указывается в самих шариатских текстах и утверждена посредством очевидных слов, а не тем способом, который упомянут в данной главе. И пусть данное исследование останется у тебя в памяти, дабы оно принесло пользу и в других вопросах."],["p","Автор (аш-Шаукани), да помилует его Аллах, в книге «Ас-сайлю ль-джаррар» (стр. 508) говорит: <i>«Не секрет, что в приводимых хадисах пророк</i> (да благословит его Аллах и приветствует) <i>упоминает вес и меру для разъяснения того, в чём должна быть одинаковость между упомянутыми им товарами при их обмене. Каким же образом данное упоминание могли преобразовать в описание, чтобы затем ко всем другим товарам и продуктам применить ту же правовую норму, что и к товарам, непосредственно упомянутым в хадисе? И как вообще на что-то другое может перейти правовая норма по причине такого рода упоминаний? Какое описание можно извлечь из этого, зная, что целью упоминания было указание на одинаковость, подобно словам:</i> <b><i>«одинаковое за одинаковое и равное за равное»?</i></b>"],["p","<i>Аш-Шафи‘и и те, кто разделил его точку зрения, обусловили ростовщические товары двумя условиями: одинаковостью категорий и съедобностью. При этом они опирались на хадис, приводимый у Муслима и у других со слов Ма‘мара ибн ‘Абду-Ллаха, который сказал: «Я слышал, как пророк</i> (да благословит его Аллах и приветствует) <i>сказал:</i> <b><i>«Бартер еды на еду производится в одинаковых количествах»,</i></b> <i>— а нашей едой в то время был ячмень»<sup>96</sup>.</i>"],["p","<i>Но, что из того, что в хадисе приходит упоминание еды? Где довод на то, что этим упоминанием, пророк</i> (да благословит его Аллах и приветствует) <i>имел в виду, что вся еда подобна тем перечисленным шести товарам? Что толкает учёных на утверждение того, что это то самое</i>"]],"notes":[[96,"Муслим (1592)."]]},{"n":812,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","<i>качество и описание ростовщических товаров, чтобы затем строить на этом мосты и возводить замки, говоря, что этот хадис является доводом на обязательное соблюдение одинаковости количества при бартере продуктов питания на продукты питания, чтобы это не стало ростовщичеством? И первое, что опровергает их аргументацию — это золото и серебро, упоминаемые в самом начале хадисов, в которых перечисляются виды товаров, при обмене которых может возникнуть ростовщичество.</i>"],["p","<i>Также из того, что опровергает упомянутые мнения — это то, что достоверно передаётся в хадисах, где пророк</i> (да благословит его Аллах и приветствует) <i>упоминал числа, как в хадисе у Муслима (1585) со слов ‘Усмана, в котором пророк</i> (да благословит его Аллах и приветствует) <i>сказал:</i> <b><i>«Не продавайте динар за два динара»</i></b><i>, а в другой версии, приводимой у аль-Бухари (2080) со слов Абу Са‘ида, говорится, что он сказал:</i> <b><i>«…и два дирхама за дирхам».</i></b> <i>Тем не менее, никто из учёных, в том числе и придерживающиеся упомянутых мнений, не говорили, что число имеет значение.</i>"],["p","Маликиты сошлись с шафиитами на том, что учитываемым описанием товара является его съедобность, а затем к этому описанию, в отличие от шафиитов, добавили ещё и длительный срок хранения, и продовольственную ценность, безосновательно раздвинув рамки ростовщических товаров."],["p","<i>В итоге, нет ни одного довода, чтобы аргументировать проведение параллели между перечисленными в хадисе и другими товарами»<sup>97</sup>.</i>"]],"notes":[[97,"Шейх аль-Альбани сказал: <i>«Ранее упоминалось два хадиса, каждый из которых по отдельности является доводом, не говоря уже об их совокупности! Вполне достаточно этих хадисов для утверждения правового постановления. Из них делается вывод, что причиной отнесения продукта к ростовщическим является его продажа по весу или по мере. Также это было мнением Ибн Таймии, который сказал: «Причиной запрета вида ростовщичества «риба́аль-фадль» является принадлежность товара к продуктам питания и их продажа через взвешивание или отмеривание. И это одно из мнений, которое передаётся от Ахмада»».</i> См. «аль-Ихтиярат» (75)."]]},{"n":813,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","frames":[{"s":"a","h":46.9,"mt":0,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":64.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","<b>• ВОПРОС № 4: НЕТ РОСТОВЩИЧЕСТВА ПРИ РАЗНОСТИ КАТЕГОРИЙ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Если же обмениваемые товары относятся к разным категориям, дозволяется отличие в их весе и объёме, при условии обмена из рук в руки».</i>",{"mt":0.34}],["p","Исходя из того, что приводится в обоих Сахихах со слов ‘Убады ибн ас-Самита, что пророк <span class=\"hon\">ﷺ</span> сказал: <i><b>«Обмен золота на золото, серебра на серебро, пшеницы на пшеницу, ячменя на ячмень, фиников на финики и соли на соль должен происходить в равных количествах и из рук в руки. Если же виды разнятся, то нет проблем в количественной разности обмениваемых товаров, если он происходит из рук в руки»</b><sup>98</sup><b>.</b></i>"],["p","В данной главе есть и другие хадисы."],["h","<b>• ВОПРОС № 5: ЗАПРЕЩЕНО ОБМЕНИВАТЬСЯ ТОВАРАМИ ОДНОГО ВИДА, КРОМЕ КАК ТОЧНО ЗНАЯ ОБ ИХ ОДИНАКОВОМ ВЕСЕ ИЛИ ОДИНАКОВОЙ МЕРЕ</b>",{"mt":0.31,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«И не дозволено продавать что-то за что-то из того же вида, кроме как зная об их одинаковой мере или весе…».</i>",{"mt":0.34}],["p","Исходя из хадисов, приводимых в обоих Сахихах, в которых пророк <span class=\"hon\">ﷺ</span> говорит: <b><i>«Одинаковым за одинаковое, равным за равное и весом за вес».</i></b> Всё это указывает на то, что нельзя применять бартер среди товаров одного вида, кроме как зная об их одинаковости и равности со стороны веса и меры."],["p","Также на это указывает хадис, приводимый у Муслима (1530) и других, со слов Джабира, который сказал: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>запретил продавать кучу фиников, мера которой неизвестна, за отмеренное количество фиников».</i>"],["p","Это указывает на то, что в таких случаях сделка запрещена, кроме как точно будет известна мера обмениваемых товаров."],["p","[Сказал аш-Шаукани]: <i>«…даже если в нём будет присутствовать что-то другое».</i>"]],"notes":[[98,"Муслим (1587–81)."]]},{"n":814,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.8,"mt":0.71,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","То есть наличие в товаре чего-то постороннего никак не влияет на необходимость равности и одинаковости веса или объёма обмениваемых товаров. И это исходя из хадиса, приводимого у Муслима (1591) и у других со слов Фадали ибн ‘Убайда, который сказал: <i>«В день Хайбара я купил за двенадцать золотых динаров колье из золота и бус. Когда я отделил бусы от золота, оказалось, что в нём золота больше чем в двенадцати динарах. И когда я рассказал об этом пророку</i> (да благословит его Аллах и приветствует)<i>, он сказал:</i> <b><i>«Такие вещи не должны продаваться и покупаться до тех пор, пока не будет отделено одно от другого»».</i></b>"],["p","Этого придерживались многие из предшественников, среди которых ‘Умар ибн аль-Хаттаб, аш-Шафи‘и, Ахмад и Исхак."],["p","Другая группа учёных, среди которых ханафиты, склонились к тому, что нет проблем в разности количества этих товаров, когда они продаются совместно с чем-то другим, и когда эта надбавка соответствует тому, за что она даётся."],["h","<b>• ВОПРОС № 6: НЕ ДОЗВОЛЕНО ПРОДАВАТЬ СВЕЖИЕ ФИНИКИ ЗА СУШЁНЫЕ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«И не дозволена продажа свежих фруктов за сушёные…».</i>",{"mt":0.34}],["p","Исходя из предшествовавшего хадиса Ибн ‘Умара, где говорилось о запрете продажи плодов финикового сада за отмеренные сушёные финики, а виноград за отмеренный изюм. А также, исходя из вышеприведённых хадисов Рафи‘а ибн Хадиджа и Сахля ибн Аби Хасмы."],["p","Также в «аль-Муватта» (2/624) имама Малика приводится хадис Са‘да о том, что он слышал, как посланник Аллаха (да благословит его Аллах и приветствует) был спрошен относительно бартера сушёных фиников на свежие и спросил: <b><i>«Уменьшается ли количество свежих фиников, когда они высыхают?».</i></b> И когда ему дали утвердительный ответ, запретил это."],["p","Этого мнения придерживался аш-Шафи‘и, а данный хадис является основным доводом того, что нельзя обмениваться продуктами питания одного вида, когда одни из них являются сушёными, а другие свежими. Например, как обмен свежих фиников (рутаб) на сушёные (тамр), обмен винограда на изюм, обмен свежего мяса на"]],"notes":[]},{"n":815,"head":"КНИГА 10. ТОРГОВЛЯ И ИНЫЕ ВЗАИМООТНОШЕНИЯ","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c","сушёное. И этого мнения придерживается большинство обладателей знания, в числе которых Малик, аш-Шафи‘и и ученики Абу Ханифы (Абу Юсуф и Мухаммад аш-Шайбани)."],["p","Однако сам Абу Ханифа дозволял это, опираясь на всеобщность смысла аята: <b>«Аллах дозволил торговлю и запретил ростовщичество»</b><sup>99</sup>, а также опираясь на аналогию (кыяс), лишённую условий её действительности, а именно, опираясь на утверждение: «Свежие и сушёные финики относятся либо к разным видам, либо к одному, но в любом случае обмен одних на другие не запрещён» (имеется в виду, не запрещён, даже без соблюдения одинаковости и отсутствия отсрочки)."],["p","Ибн аль-Кайим сказал: <i>«Если ты посмотришь на эту аналогию, увидишь, что она наиполнейшим образом противоречит Сунне, и это при том, что эта аналогия сама по себе является неправильной. А что касается свежих и сушёных фиников, то они относятся к одному виду, где одно больше другого вне зависимости от намерения. Одно из них больше другого, и эту разность невозможно определить, а посему, невозможно и покрыть её, так как все это будет опираться лишь на предположение. И даже если бы в Сунне не пришёл запрет подобной сделки, на её запрет указала бы аналогия (аль-кыяс). Но даже при отсутствии аналогии, неприемлемость подобной сделки должна была бы стать основой, которой необходимо было бы придерживаться и подчинить себя ей, подобно тому, как человек принимает и подчиняет себя Священным текстам».</i>"],["h","<b>• ВОПРОС № 7: ПОСЛАБЛЕНИЯ В ПРОДАЖЕ «АЛЬ-‘АРÁЯ (мн.ч)»</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«…кроме обладателей «аль-‘ара́я»<sup>100</sup>…».</i>",{"mt":0.33}],["p","Исходя из хадиса, приводимого у аль-Бухари и других со слов Зайда ибн Сабита о том, что пророк (да благословит его Аллах и приветствует) сделал послабление в отношении «аль-‘арáя», когда отмеренное количество фруктов обменивается на свежие, определённые на глаз<sup>101</sup>."]],"notes":[[99,"Сура «аль-Бакара», аят 275."],[100,"«аль-‘А́рия» — это бесплатное предоставление права пользования чем-либо. См. «ат-Та‘рифату ль-Джурджани» (146). В данном случае имеются в виду пальмы, предоставленные для пользования неимущим."],[101,"Аль-Бухари (2184), Муслим (1539)."]]}];
